BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "last_wall_distance": None,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Adjust whisker threshold to delay backward force application
    if front < 1.5:  # Higher threshold to delay backward force application
        # Apply backward force to avoid collision
        sandbox.apply_agent_force(-35.0, 0.0)
        state["last_wall_distance"] = front
    else:
        state["last_wall_distance"] = None

    if state["phase"] == "APPROACH":
        # Calculate forward force based on distance to activation zone and velocity
        if x < ACTIVATION_X_MIN:
            # Higher forward force to overcome damping and wall proximity
            # Use velocity to dynamically adjust force
            if abs(vxd) < 0.5:
                fx = 120.0  # Increased from 100 to 120 N
            else:
                fx = 100.0  # Slightly lower to prevent overshooting
        else:
            # Gradually reduce force as approaching activation zone
            fx = 10.0 * (ACTIVATION_X_MIN - x) - 5.0 * vxd
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check if entering activation zone and velocity is low enough
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply backward force to meet unlock condition
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        # Ensure Fx is strictly less than -34 N
        fx_cmd = -35.0  # Slightly below threshold
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on velocity to maintain speed
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply forward force to move towards exit
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Apply zero force to hold in exit zone
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

